<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\DispatchService;use App\Security\Csrf;Auth::requirePermission('TRIP_VIEW_OPERATIONS');$id=(int)($_GET['id']??0);$errors=[];$r=DispatchService::find($id);if(!$r){http_response_code(404);exit('Trip not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid token.';else try{DispatchService::transition($id,$_POST['to']??'',(int)Auth::user()['id'],true);header('Location: ?id='.$id.'&updated=1');exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}$r=DispatchService::find($id);}$stops=DispatchService::stops($id);$next=['planned'=>'driver_ready','driver_ready'=>'dispatched','dispatched'=>'in_transit','in_transit'=>'arrived','arrived'=>'delivered'][$r['current_status']]??null;$pageTitle='Trip '.$r['trip_ref'];require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1><?=h($r['trip_ref'])?></h1><p><?=h($r['load_ref'].' · '.$r['origin_city'].' → '.$r['destination_city'])?></p></div><span class="badge"><?=h($r['current_status'])?></span></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><div class="card"><p><?=h($r['registration_number'].' · Driver '.$r['driver_name'])?></p><p>Departure: <?=h($r['planned_departure_at'])?> · Arrival: <?=h($r['planned_arrival_at'])?></p><p><a href="<?=h(\App\Support\Url::to('tracking/view.php?id='.$id))?>">Open tracking, alerts & exceptions</a></p><?php foreach($stops as$s):?><p><?=h($s['sequence_no'].'. '.$s['name'].' — '.$s['address_line'].', '.$s['city'])?></p><?php endforeach;?></div><?php if($next&&Auth::can($next==='dispatched'?'TRIP_DISPATCH':'TRIP_STATUS_OPERATIONS')):?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="to" value="<?=h($next)?>"><button class="button">Operations update: <?=h(str_replace('_',' ',$next))?></button></form><?php endif;?><?php require BASE_PATH.'/app/Views/layout/footer.php';
